table(['Forecast-date usage group','N','Production MAE / RMSE','Full-role MAE / RMSE','Benchmark expected MAE / RMSE'],[[g,get(g,'production','PA' if g in ['everyday','platoon','bench'] else 'IP')['n']]+[f(get(g,m,'PA' if g in ['everyday','platoon','bench'] else 'IP')['MAE'])+' / '+f(get(g,m,'PA' if g in ['everyday','platoon','bench'] else 'IP')['RMSE']) for m in ['production','full_role','expected_benchmark']] for g in ['everyday','platoon','bench','starter','reliever']]),
