table(['Player / role','Production PA/IP','Full-role PA/IP','Expected benchmark PA/IP','Production surplus','Full-role surplus','Expected surplus'],[[x['name']+' / '+x['cohort']]+[f(x[m+'_'+('PA' if x['role']=='H' else 'IP')]) for m in ['production','full_role','expected_benchmark']]+[f(x[m+'_replacement_surplus']) for m in ['production','full_role','expected_benchmark']] for x in examples]),
